    bestv = 10**18
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not ok(nx, ny):
            continue
        v = dist(nx, ny, tx, ty)
        if v < bestv:
            bestv = v
            bestm = (dx, dy)
        elif v == bestv:
